import Product from '../../product/product.model.js';

export class VectorSearchService {
  /**
   * Executes native MongoDB Atlas Vector Search on the products collection.
   * Finds visually or semantically similar clothing items using cosine similarity.
   *
   * @param {number[]} queryVector - Dense vector embedding generated by the local VLM
   * @param {number} [limit=4] - Number of top matches to retrieve
   * @param {number} [minScore=0.70] - Minimum cosine similarity threshold
   * @returns {Promise<Array>} List of matched product documents with similarity scores
   */
  static async searchByVector(queryVector, limit = 4, minScore = 0.70) {
    if (!queryVector || !Array.isArray(queryVector) || queryVector.length === 0) {
      return [];
    }

    try {
      const pipeline = [
        {
          $vectorSearch: {
            index: 'product_vector_index',
            path: 'embedding',
            queryVector: queryVector,
            numCandidates: Math.max(50, limit * 10),
            limit: limit,
            filter: {
              isActive: true,
            },
          },
        },
        {
          $project: {
            name: 1,
            slug: 1,
            price: 1,
            discount: 1,
            images: 1,
            sku: 1,
            sizes: 1,
            category: 1,
            score: { $meta: 'vectorSearchScore' },
          },
        },
        {
          $match: {
            score: { $gte: minScore },
          },
        },
      ];

      const results = await Product.aggregate(pipeline);
      return results;
    } catch (err) {
      // If the Atlas Vector index is not yet built, log warning and gracefully return empty array
      console.warn(`⚠️ MongoDB Atlas Vector Search fallback: ${err.message}`);
      return [];
    }
  }
}
